    15	// Adapter utility from fuzzer input to a temporary file, for fuzzing APIs that
    16	// require a file instead of an input buffer.
    17	
    18	#include <cstddef>
    19	#include <cstdint>
    20	#include <cstdlib>
    21	#include <string>
    22	#include <vector>
    23	
    24	#include "fuzzer_temp_file.h"
    25	#include "matio.h"
