    27	extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    28	  FuzzerTemporaryFile temp_file(data, size);
    29	
    30	  mat_t* matfd = Mat_Open(temp_file.filename(), MAT_ACC_RDONLY);
    31	  if (matfd == nullptr) {
    32	    return 0;
    33	  }
    34	
    35	  size_t n = 0;
    36	  Mat_GetDir(matfd, &n);
    37	  Mat_Rewind(matfd);
    38	
    39	  matvar_t* matvar = nullptr;
    40	  while ((matvar = Mat_VarReadNextInfo(matfd)) != nullptr) {
    41	    Mat_VarReadDataAll(matfd, matvar);
    42	    Mat_VarGetSize(matvar);
    43	    Mat_VarFree(matvar);
    44	  }
    45	
    46	  Mat_Close(matfd);
    47	
    48	  return 0;
    49	}
